/**
 * The support code generated tests import (ADR-129 §3), as source text.
 *
 * Each is written into the MFE once and owned by it, like every generated test
 * file, so an MFE's tests carry no dependency on this tool. They are kept
 * dependency-free: what an MFE already has (Jest, jsdom, Testing Library,
 * Playwright) is all they use. `__tests__/harness.test.ts` transpiles and runs
 * them, so the text below is executed code, not an unchecked string.
 */

export const GENERATED_MARK = 'Generated by seans-mfe-tool test:generate (ADR-129)';

/**
 * Answers a test's network from a capture's recorded responses: `fetch` and
 * `XMLHttpRequest` both, so an axios client and a fetch client are served the
 * same way. A request with no recording is answered 404 and listed in
 * `unexpected`, so a test can say the code asked for something the captured app never did.
 */
export const RECORDED_NETWORK = `/**
 * Recorded network for characterization tests — ${GENERATED_MARK}.
 *
 * Serves fetch and XMLHttpRequest from what a capture recorded, keyed
 * \`METHOD url\` with the URL relative to the page's origin. Developer-owned once
 * written: test:generate will not overwrite it after you change it.
 */

export interface RecordedResponse {
  status: number;
  mimeType: string;
  body: unknown;
}

export interface RecordedNetwork {
  /** \`METHOD url\` of every request made, in order. */
  calls: string[];
  /** Requests with no recording, answered 404. */
  unexpected: string[];
  restore(): void;
}

type Listener = (event: { type: string }) => void;

function originOf(): string {
  const loc = (globalThis as { location?: { origin?: string } }).location;
  return loc?.origin && loc.origin !== 'null' ? loc.origin : 'http://localhost';
}

/** The key a capture records a request under: app-relative when it is on the page's origin. */
export function requestKey(method: string, url: string): string {
  const origin = originOf();
  let rel = url;
  try {
    const u = new URL(url, origin);
    rel = u.origin === origin ? u.pathname + u.search : u.toString();
  } catch {
    // keep the URL as given
  }
  return \`\${method.toUpperCase()} \${rel}\`;
}

function bodyText(r: RecordedResponse): string {
  return typeof r.body === 'string' ? r.body : JSON.stringify(r.body);
}

export function installRecordedNetwork(responses: Record<string, RecordedResponse>): RecordedNetwork {
  const calls: string[] = [];
  const unexpected: string[] = [];
  const answer = (method: string, url: string): RecordedResponse => {
    const key = requestKey(method, url);
    calls.push(key);
    const hit = responses[key];
    if (hit) return hit;
    unexpected.push(key);
    return { status: 404, mimeType: 'application/json', body: { error: \`no recording for \${key}\` } };
  };

  const g = globalThis as unknown as Record<string, unknown>;
  const saved = { fetch: g.fetch, XMLHttpRequest: g.XMLHttpRequest };

  g.fetch = async (input: unknown, init?: { method?: string }) => {
    const url = typeof input === 'string' ? input : String((input as { url?: string }).url ?? input);
    const method = init?.method ?? (input as { method?: string }).method ?? 'GET';
    const r = answer(method, url);
    const text = bodyText(r);
    return {
      ok: r.status >= 200 && r.status < 300,
      status: r.status,
      statusText: String(r.status),
      url,
      headers: { get: (h: string) => (h.toLowerCase() === 'content-type' ? r.mimeType : null) },
      json: async () => JSON.parse(text),
      text: async () => text,
      clone() {
        return this;
      },
    };
  };

  class RecordedXhr {
    static readonly UNSENT = 0;
    static readonly OPENED = 1;
    static readonly HEADERS_RECEIVED = 2;
    static readonly LOADING = 3;
    static readonly DONE = 4;
    readyState = 0;
    status = 0;
    statusText = '';
    response: unknown = null;
    responseText = '';
    responseURL = '';
    responseType = '';
    timeout = 0;
    withCredentials = false;
    upload = { addEventListener: () => undefined, removeEventListener: () => undefined };
    onreadystatechange: Listener | null = null;
    onload: Listener | null = null;
    onloadend: Listener | null = null;
    onerror: Listener | null = null;
    onabort: Listener | null = null;
    ontimeout: Listener | null = null;
    private method = 'GET';
    private url = '';
    private mime = '';
    private aborted = false;
    private listeners: Record<string, Listener[]> = {};
    open(method: string, url: string): void {
      this.method = method;
      this.url = url;
      this.readyState = 1;
    }
    setRequestHeader(): void {}
    overrideMimeType(): void {}
    getResponseHeader(name: string): string | null {
      return name.toLowerCase() === 'content-type' ? this.mime : null;
    }
    getAllResponseHeaders(): string {
      return this.mime ? \`content-type: \${this.mime}\\r\\n\` : '';
    }
    addEventListener(type: string, fn: Listener): void {
      (this.listeners[type] ??= []).push(fn);
    }
    removeEventListener(type: string, fn: Listener): void {
      this.listeners[type] = (this.listeners[type] ?? []).filter((l) => l !== fn);
    }
    abort(): void {
      this.aborted = true;
      this.fire('abort');
    }
    send(): void {
      const r = answer(this.method, this.url);
      setTimeout(() => {
        if (this.aborted) return;
        this.status = r.status;
        this.statusText = String(r.status);
        this.mime = r.mimeType;
        this.responseURL = new URL(this.url, originOf()).toString();
        this.responseText = bodyText(r);
        this.response = this.responseType === 'json' ? r.body : this.responseText;
        this.readyState = 4;
        this.fire('readystatechange');
        this.fire('load');
        this.fire('loadend');
      }, 0);
    }
    private fire(type: string): void {
      const event = { type };
      const own = (this as unknown as Record<string, Listener | null>)[\`on\${type}\`];
      if (own) own.call(this, event);
      for (const l of this.listeners[type] ?? []) l.call(this, event);
    }
  }
  g.XMLHttpRequest = RecordedXhr;

  return {
    calls,
    unexpected,
    restore() {
      g.fetch = saved.fetch;
      g.XMLHttpRequest = saved.XMLHttpRequest;
    },
  };
}

/**
 * The first chunk of \`expected\` the page does not show, in order, or null when
 * it shows them all. Whitespace is ignored: a page's text runs adjacent
 * elements together, a capture's separates them.
 */
export function missingText(pageText: string, expected: string): string | null {
  const page = pageText.replace(/\\s+/g, '');
  let at = 0;
  for (const chunk of expected.split(/\\s+/).filter(Boolean)) {
    const i = page.indexOf(chunk, at);
    if (i < 0) return chunk;
    at = i + chunk.length;
  }
  return null;
}
`;

/**
 * Console noise jsdom adds that a browser never shows: React's act() warning
 * and jsdom's own "not implemented" notices. Generated alone tests ignore these
 * and nothing else.
 */
export const JSDOM_NOISE = [/not wrapped in act\(/, /Not implemented: /, /ReactDOMTestUtils\.act/];
